import math

def solve():
    taxable_income = 75000.0
    tax_brackets = [20000.0, 50000.0, 100000.0]
    tax_rates = [0.10, 0.15, 0.20]

    def calculate_tax_liability(taxable_income: float, tax_brackets: list, tax_rates: list) -> float:
        if len(tax_brackets) != len(tax_rates):
            raise ValueError("Tax brackets and tax rates must have the same length.")

        tax_liability = 0.0
        for i, rate in enumerate(tax_rates):
            if i == 0:
                lower_bound = 0.0
            else:
                lower_bound = tax_brackets[i-1]

            upper_bound = tax_brackets[i]

            if taxable_income > lower_bound:
                amount_to_tax = min(taxable_income, upper_bound) - lower_bound
                tax_liability += amount_to_tax * rate

        # This part of the original function handles income exceeding the last defined bracket.
        # In this specific problem, the income (75000) does not exceed the last bracket (100000),
        # so this condition is not met, and it correctly means any income past the last bracket
        # continues to be taxed at the last rate.
        # However, for the given income, the loop already covers up to 100000, so this part isn't strictly needed for 75000.
        # If taxable_income were, say, 120000, this line would tax the 20000 above 100000 at the last rate (0.20).
        if taxable_income > tax_brackets[-1]:
            tax_liability += (taxable_income - tax_brackets[-1]) * tax_rates[-1]

        return tax_liability

    total_tax = calculate_tax_liability(taxable_income, tax_brackets, tax_rates)

    # Round to the nearest dollar as requested
    return round(total_tax)

