import math

def solve():
    initial_book_value = 120000.0
    salvage_value = 10000.0
    useful_life_years = 5
    year = 3

    def calculate_doubling_declining_balance_depreciation(initial_book_value: float, salvage_value: float, useful_life_years: int, year: int) -> float:
        if year < 1 or year > useful_life_years:
            raise ValueError("Year must be within the useful life of the asset")

        book_value = initial_book_value
        straight_line_rate = 1 / useful_life_years
        double_declining_rate = 2 * straight_line_rate

        current_year_depreciation = 0.0

        for current_year in range(1, year + 1):
            if book_value <= salvage_value:
                current_year_depreciation = 0.0 # No more depreciation once book value hits salvage value
                break

            depreciation_allowed = (book_value * double_declining_rate)

            # Ensure book value does not go below salvage value
            if (book_value - depreciation_allowed) < salvage_value:
                current_year_depreciation = book_value - salvage_value
                book_value = salvage_value
            else:
                current_year_depreciation = depreciation_allowed
                book_value -= current_year_depreciation

            if current_year == year:
                return round(current_year_depreciation)

        return round(current_year_depreciation)

    result = calculate_doubling_declining_balance_depreciation(initial_book_value, salvage_value, useful_life_years, year)
    return int(result)

