import math

def solve():
    principal = 250000
    annual_interest_rate = 3.75
    years = 30

    def calculate_amortization_schedule(principal: float, annual_interest_rate: float, years: int) -> list:
        monthly_interest_rate = annual_interest_rate / 100 / 12
        num_payments = years * 12

        # Calculate monthly payment
        if monthly_interest_rate == 0:
            monthly_payment = principal / num_payments
        else:
            monthly_payment = (principal * monthly_interest_rate) / (1 - (1 + monthly_interest_rate) ** -num_payments)

        schedule = []
        remaining_balance = principal

        for month in range(1, num_payments + 1):
            interest_payment = remaining_balance * monthly_interest_rate
            principal_payment = monthly_payment - interest_payment

            # Adjust last payment to clear remaining balance if there's a small discrepancy
            if month == num_payments and remaining_balance > 0 and remaining_balance < principal_payment + interest_payment:
                principal_payment = remaining_balance + principal_payment - (round(monthly_payment,2) - round(interest_payment,2))
                remaining_balance = 0
            else:
                remaining_balance -= principal_payment

            if remaining_balance < 0 and month != num_payments: # Should not happen for fully amortizing, but as a safeguard
                remaining_balance = 0

            schedule.append({
                'month': month,
                'payment': round(monthly_payment, 2),
                'principal': round(principal_payment, 2),
                'interest': round(interest_payment, 2),
                'remaining_balance': round(remaining_balance, 2)
            })

        return schedule

    amortization_schedule = calculate_amortization_schedule(principal, annual_interest_rate, years)

    total_principal_paid_first_12_months = 0
    for i in range(12):
        if i < len(amortization_schedule):
            total_principal_paid_first_12_months += amortization_schedule[i]['principal']

    return round(total_principal_paid_first_12_months)

