import math
import json

def solve():
    amt_income = 150000
    exemption = 50000
    brackets_str = "{\"0\": 0.26, \"120000\": 0.28}"
    brackets = json.loads(brackets_str)

    # Convert string keys to int for brackets dictionary
    parsed_brackets = {int(k): v for k, v in brackets.items()}

    taxable_amt_income = max(0, amt_income - exemption)

    tmt = 0.0
    for threshold, rate in sorted(parsed_brackets.items(), reverse=True):
        if taxable_amt_income > threshold:
            tmt += (taxable_amt_income - threshold) * rate
            taxable_amt_income = threshold

    return round(tmt)

